from lib import *
S = SS('w2')
steps = [
    step("在真实网卡 en0 上抓 20 秒(期间让本机发一点 curl、dig、ping),共抓到 4007 个以太网帧,EtherType 分布:0x0800(IPv4)3899 个、0x0806(ARP)70 个、0x86dd(IPv6)14 个,还有 0x9998、0x2589 等不认识的厂商私有类型。目的地址种类:单播 3306、广播 ff:ff:ff:ff:ff:ff 372、IPv4 组播(01:00:5e:…)317、IPv6 组播(33:33:…)12。帧长(不含 FCS)最小 42、最大 1506、中位数 102 字节。EtherType 决定载荷交给谁:0x0800 给 IPv4、0x0806 给 ARP、0x86dd 给 IPv6。", t=tl(S(1)), mark=lidx(S(1), 'EtherType 分布', '目的地址种类'), done=lidx(S(1), '20 秒共抓到', '帧长'), b=bars([['IPv4 0x0800', 3899, '3899'], ['ARP 0x0806', 70, '70'], ['IPv6 0x86dd', 14, '14']], 3899, mark=[1, 2], done=[0]), kv=KV([['EtherType 0x0800', '载荷是 IPv4'], ['0x0806', 'ARP'], ['0x86dd', 'IPv6'], ['目的地址', '单播 / 广播 / 组播']], ['EtherType 0x0800'])),
    step("MAC 地址的两个标志位在第一个字节里:最低位=组播位,次低位=本地管理位。本机网卡 MAC 7e:aa:6f:…,第一个字节 0x7e → 组播位 0、本地管理位 1:系统生成的随机私有地址,不是出厂烧录的;默认网关 70:85:6c:…,0x70 → 本地管理位 0,是厂商烧录的全局唯一地址(前 3 字节是厂商 OUI);广播地址 ff:ff:ff:ff:ff:ff 两位都是 1。IPv4 组播的目的 MAC 01:00:5e:00:00:fb 对应 IP 224.0.0.251(mDNS):MAC 的低 23 位直接取自 IP 地址。", t=tl(S(2)), mark=lidx(S(2), '本机网卡', '默认网关'), done=lidx(S(2), '广播地址', 'IPv4 组播目的'), kv=KV([['第一个字节最低位', '1 = 组播 / 广播'], ['第一个字节次低位', '1 = 本地管理(随机 / 虚拟)'], ['IPv4 组播 MAC', '01:00:5e + IP 低 23 位']], ['第一个字节次低位'])),
    step("最小帧长:ping 一个不存在的邻居 IP 触发 ARP。本机发出的 ARP 请求在抓包里帧长 42 字节 = 14 以太网头 + 28 ARP;以太网规定最小帧是 64 字节(含 4 字节 FCS),差额由网卡在发送时补零——抓包点在网卡之前,所以看不到补零。反过来,别的设备回来的 ARP 应答在抓包里是 60 字节:对方网卡已经补到 60,我们抓到的是补过零的帧(FCS 4 字节另算,合起来 64)。ARP 请求是广播,目的 ff:ff:ff:ff:ff:ff,EtherType 0x0806。", t=tl(S(3)), mark=lidx(S(3), '本机发出的 ARP 请求帧长', '别的设备回来的'), done=lidx(S(3), 'ARP, Request who-has'), b=bars([['本机发出的 ARP 请求(抓包点在网卡前)', 42, '42 B'], ['对方的 ARP 应答(已补零)', 60, '60 B'], ['线上最小帧(含 FCS)', 64, '64 B']], 64, mark=[0], done=[1, 2]), kv=KV([['ARP 请求(本机发)', '42 字节,未补零'], ['ARP 应答(对方发)', '60 字节,已补零'], ['线上最小帧', '64 字节 = 60 + FCS 4']], ['线上最小帧'])),
    step("最大帧长和 MTU:以太网载荷最大 1500。ping -D(不分片)-s 1472:ICMP 头 8 + 数据 1472 + IP 头 20 = 1500,请求和应答抓到的帧长都是 1514(14 + 20 + 8 + 1472),这是标准以太网帧去掉 FCS 之后的最大值(含 FCS 是 1518);ping -D -s 1473 多 1 字节,本机直接报 ping: sendto: Message too long,网线上没有出现新的帧。", t=tl(S(4)), mark=lidx(S(4), '-s 1473'), done=lidx(S(4), '-s 1472', '抓到的 ICMP 帧长'), b=bars([['-s 1472 的帧长', 1514, '1514 B'], ['含 FCS', 1518, '1518 B']], 1518, mark=[0], done=[1]), kv=KV([['-s 1472', '帧长 1514,通过'], ['-s 1473', 'Message too long,不发'], ['MTU', '1500(载荷上限)']], ['MTU'])),
    step("FCS 去哪了:以太网帧尾有 4 字节 CRC-32,网卡发送时加、接收时校验后剥掉,所以抓包文件里没有。用 Python 的 zlib.crc32 对那个 42 字节的 ARP 请求帧(不含补零)算出 0x83f1343a,只是说明它是怎么来的:真实发送时先补零到 60 字节再算 FCS 附在尾部,字节序是小端。线上完整帧 = 60 + 4 = 64 字节。", t=tl(S(5)), mark=lidx(S(5), '0x83f1343a'), done=lidx(S(5), '线上的完整帧'), kv=KV([['FCS', '4 字节 CRC-32,在帧尾'], ['抓包里', '看不到(网卡剥掉了)'], ['线上完整帧', '60 + 4 = 64']], ['FCS'])),
]
A = mkartw('w2', 2, '网络协议,以太网帧,MAC地址,EtherType,最小帧长,FCS,tcpdump,真实验证,动画演示',
    '在真实网卡上抓 4007 个以太网帧:EtherType 0x0800/0x0806/0x86dd 决定载荷,目的地址分单播 / 广播 / 组播;MAC 第一个字节的两个标志位(本机的随机私有地址 0x7e vs 网关的全局地址 0x70);ARP 请求抓到 42 字节、对方的应答 60 字节,线上最小帧 64;ping -D -s 1472 帧长 1514,1473 被本机拒绝;FCS 抓包里看不到。',
    '以太网帧头只有 14 字节,却决定了数据交给谁、发给谁、能多大。这篇在真实网卡上抓帧,看 EtherType、MAC 的标志位、最小帧长补零、MTU 边界,以及抓包里永远看不到的 FCS。',
    [('4007 帧', '20 秒里在真实网卡上抓到的以太网帧数(IPv4 3899、ARP 70、IPv6 14)'), ('42 vs 60', '本机发的 ARP 请求与对方回的 ARP 应答在抓包里的帧长——补零发生在网卡'), ('1514', 'ping -D -s 1472 的帧长;多 1 字节(1473)就被拒绝')],
    [('帧头', '<p>以太网帧头 14 字节:目的 MAC 6、源 MAC 6、EtherType 2。EtherType 决定载荷交给 IPv4(0x0800)、ARP(0x0806)还是 IPv6(0x86dd)。</p>'),
     ('MAC 的两个标志位', '<p>第一个字节最低位是组播位(广播也是组播的一种),次低位是本地管理位:随机私有地址和虚拟网卡的本地管理位为 1,厂商烧录的全局地址为 0。IPv4 组播的 MAC 由 01:00:5e 加 IP 低 23 位构成。</p>'),
     ('最小帧', '<p>以太网最小帧 64 字节(含 FCS),短的帧由网卡补零;抓包点在网卡之前时看到的 ARP 请求是 42 字节,收到的别人发来的已经补过零,是 60 字节。</p>'),
     ('最大帧与 MTU', '<p>载荷最大 1500,帧去掉 FCS 最大 1514(含 FCS 1518)。ping -D -s 1473 超过 MTU,本机直接拒绝发送。</p>'),
     ('FCS', '<p>帧尾的 4 字节 CRC-32 由网卡硬件加和校验,抓包文件里不存在。</p>')],
    steps,
    [ENV_W + '。第一节在 en0 上不加过滤抓 20 秒,统计包括网络里其它设备发出的广播和组播;MAC 地址只保留前 3 字节;ARP 与 ICMP 的节用的是真实的默认网关和一个同网段不存在的 IP;FCS 的数字是 zlib.crc32 的计算值,不是抓到的',
     '没有验证:802.11(Wi-Fi)的帧格式(en0 上 tcpdump 给的是以太网伪头);VLAN 标签帧;巨型帧(MTU 9000);网卡 TSO / LRO 下抓到的超大帧;FCS 错误帧的计数(需要网卡统计);交换机如何处理帧(学习与转发,见后面的篇目)'],
    '以太网帧')
